 s(22, 'divider', 'EMC Test Results and Standards',
   'Section title with a life-cycle strip: concept, feasibility, development, test, delivery.',
   'Tiêu đề phần kèm dải vòng đời: khái niệm, khả thi, phát triển, thử nghiệm, bàn giao.',
   formulas=[], numbers=[], issues=[], basis='summary'),
 s(23, 'content', 'EMC standards',
   'An EMC standard is terminology plus rules plus test methods plus limits. Emission: CISPR 32 (multimedia), CISPR 11 (ISM); immunity: IEC 61000-4-2 (ESD), -4-3 (radiated RF field), -4-4 (EFT/burst), -4-5 (surge).',
   'Chuẩn EMC là thuật ngữ cộng quy tắc cộng phương pháp thử cộng giới hạn. Phát xạ: CISPR 32 (đa phương tiện), CISPR 11 (ISM); miễn nhiễm: IEC 61000-4-2 (ESD), -4-3 (trường RF bức xạ), -4-4 (EFT/burst), -4-5 (surge).',
   formulas=[], numbers=[], issues=[], basis='summary'),
 s(24, 'content', 'Test results diagram',
   'Diagram of test results: RI (61000-4-3, -4-39, -4-8), ESD (61000-4-2), CI (61000-4-6, -4-4, -4-5), CE (CISPR 11/32, FCC 15/18), RE, voltage dips (61000-4-11), harmonics and flicker (61000-3-2, 3-3); LISN.',
   'Sơ đồ kết quả thử: RI (61000-4-3, -4-39, -4-8), ESD (61000-4-2), CI (61000-4-6, -4-4, -4-5), CE (CISPR 11/32, FCC 15/18), RE, sụt áp (61000-4-11), hài và nhấp nháy (61000-3-2, 3-3); LISN.',
   formulas=[], numbers=[], issues=[], basis='summary'),
